<script setup lang="ts">
import {onMounted,ref} from "vue";
import {apiGet,apiPatch,apiPost,getApiErrorMessage} from "../lib/api";
import {useSessionStore} from "../stores/session";
import {useToastStore} from "../stores/toasts";
interface OtStatus{id:number;name:string;color:string;sort_order:number;active:boolean;is_initial:boolean;is_final:boolean;marks_quoted:boolean;marks_awaiting_quote_approval:boolean;marks_repair:boolean;marks_completed:boolean;marks_delivered:boolean}
const session=useSessionStore(),toast=useToastStore(),statuses=ref<OtStatus[]>([]),loading=ref(false),showNew=ref(false);
const fresh=()=>({name:"",color:"#3B82F6",sort_order:90,active:true,is_initial:false,is_final:false,marks_quoted:false,marks_awaiting_quote_approval:false,marks_repair:false,marks_completed:false,marks_delivered:false});const newStatus=ref(fresh());
async function load(){loading.value=true;try{statuses.value=await apiGet<OtStatus[]>("/work-orders/statuses")}catch(e){toast.push(getApiErrorMessage(e),"error")}finally{loading.value=false}}
async function save(st:OtStatus){try{await apiPatch("/work-orders/statuses/"+st.id,st);await load();toast.push("Estado guardado","success")}catch(e){toast.push(getApiErrorMessage(e),"error")}}
async function create(){try{await apiPost("/work-orders/statuses",newStatus.value);showNew.value=false;newStatus.value=fresh();await load();toast.push("Estado creado","success")}catch(e){toast.push(getApiErrorMessage(e),"error")}}
onMounted(load);
</script>
<template><div class="card"><div class="flex flex--between heading"><div><h2>Estados de órdenes de trabajo</h2><p class="text-secondary">Flujo propio de {{session.activeCompany?.name}}. El color de cada estado identifica también las filas de las OT.</p></div><button class="btn btn--primary" @click="showNew=true">+ Nuevo estado</button></div><div v-if="loading" class="text-muted">Cargando estados…</div><div v-else class="status-admin"><div v-for="st in statuses" :key="st.id" class="row" :style="{'--status-color':st.color,background:st.color+'16',borderColor:st.color+'55'}"><input v-model="st.color" class="color" type="color"><div class="field name"><label>Nombre</label><input v-model="st.name"></div><div class="field order"><label>Orden</label><input v-model.number="st.sort_order" type="number" min="0"></div><label class="check"><input v-model="st.active" type="checkbox"> Activo</label><label class="check"><input v-model="st.is_initial" type="checkbox"> Inicial</label><label class="check"><input v-model="st.marks_quoted" type="checkbox"> Presupuesto generado</label><label class="check"><input v-model="st.marks_awaiting_quote_approval" type="checkbox"> Espera aprobación</label><label class="check"><input v-model="st.marks_repair" type="checkbox"> En reparación</label><label class="check"><input v-model="st.marks_completed" type="checkbox"> Finaliza trabajo</label><label class="check"><input v-model="st.marks_delivered" type="checkbox"> Entrega equipo</label><button class="btn btn--ghost btn--sm" @click="save(st)">Guardar</button></div></div><p class="text-muted note">“Presupuesto generado” identifica el estado al que pasa automáticamente la OT al emitir un presupuesto. “Finaliza trabajo” registra la finalización técnica. “Entrega equipo” registra la entrega real al cliente.</p></div><div v-if="showNew" class="modal-backdrop"><div class="modal card status-modal"><div class="flex flex--between"><h2>Nuevo estado de OT</h2><button class="btn btn--ghost" @click="showNew=false">×</button></div><div class="field"><label>Nombre *</label><input v-model="newStatus.name" autofocus></div><div class="field__row"><div class="field"><label>Color</label><input v-model="newStatus.color" class="color color--large" type="color"></div><div class="field"><label>Orden</label><input v-model.number="newStatus.sort_order" type="number" min="0"></div></div><div class="flags"><label class="check"><input v-model="newStatus.active" type="checkbox"> Activo</label><label class="check"><input v-model="newStatus.is_initial" type="checkbox"> Estado inicial</label><label class="check"><input v-model="newStatus.marks_quoted" type="checkbox"> Presupuesto generado</label><label class="check"><input v-model="newStatus.marks_awaiting_quote_approval" type="checkbox"> Espera aprobación</label><label class="check"><input v-model="newStatus.marks_repair" type="checkbox"> En reparación</label><label class="check"><input v-model="newStatus.marks_completed" type="checkbox"> Finaliza trabajo</label><label class="check"><input v-model="newStatus.marks_delivered" type="checkbox"> Entrega equipo</label></div><div class="flex flex--between" style="margin-top:20px"><button class="btn btn--ghost" @click="showNew=false">Cancelar</button><button class="btn btn--primary" :disabled="!newStatus.name.trim()" @click="create">Crear estado</button></div></div></div></template>
<style scoped>.heading{align-items:flex-start;gap:16px}.heading h2{margin:0 0 6px}.status-admin{display:flex;flex-direction:column;margin-top:18px}.row{display:grid;grid-template-columns:52px minmax(150px,1fr) 80px repeat(7,auto) auto;align-items:end;gap:12px;margin:6px 0;padding:12px;border:1px solid;border-left:4px solid var(--status-color);border-radius:12px}.color{width:44px;height:40px;padding:2px;border-radius:9px;cursor:pointer}.color--large{width:72px}.name,.order{margin:0}.check{display:flex;align-items:center;gap:6px;min-height:40px;white-space:nowrap;font-size:13px}.note{margin:16px 0 0}.modal-backdrop{position:fixed;inset:0;z-index:140;background:rgba(2,6,23,.72);display:grid;place-items:center;padding:20px}.status-modal{width:min(620px,100%)}.flags{display:flex;gap:18px;flex-wrap:wrap;margin-top:12px}@media(max-width:1000px){.row{grid-template-columns:52px 1fr 80px}.row .check,.row .btn{grid-column:2/4}.heading{flex-direction:column}}@media(max-width:600px){.row{grid-template-columns:48px 1fr}.order{grid-column:2}.row .check,.row .btn{grid-column:1/3}}</style>